package com.xianshuyuan.scm.order.service;import com.xianshuyuan.scm.common.exception.BusinessException;import com.xianshuyuan.scm.order.entity.*;import com.xianshuyuan.scm.order.mapper.*;import com.xianshuyuan.scm.order.vo.*;import java.util.List;import org.springframework.stereotype.Service;@Service public class AfterSalesQueryService{private final OrderReturnMapper returns;private final OrderReturnItemMapper items;private final OrderRefundMapper refunds;public AfterSalesQueryService(OrderReturnMapper r,OrderReturnItemMapper i,OrderRefundMapper f){returns=r;items=i;refunds=f;}public OrderReturnResponse getReturn(long id){var e=returns.selectActiveById(id);if(e==null)throw new BusinessException(AfterSalesErrorCodes.RETURN_NOT_FOUND);return map(e);}public List<OrderReturnResponse> byOrder(long orderId){return returns.selectByOrderId(orderId).stream().map(this::map).toList();}public OrderRefundResponse getRefund(long id){var e=refunds.selectActiveById(id);if(e==null)throw new BusinessException(AfterSalesErrorCodes.REFUND_NOT_FOUND);return map(e);}private OrderReturnResponse map(OrderReturnEntity e){var rows=items.selectByReturnId(e.getId()).stream().map(x->new OrderReturnResponse.Item(x.getId(),x.getOrderItemId(),x.getRequestedQuantity(),x.getApprovedQuantity(),x.getLockedUnitPrice(),x.getApprovedAmount(),x.getVersion())).toList();var f=refunds.selectByReturnId(e.getId());return new OrderReturnResponse(e.getId(),e.getReturnNo(),e.getOrderId(),e.getCustomerId(),e.getStatus(),e.getReason(),e.getDecisionReason(),e.getApprovedAmount(),e.getVersion(),e.getCreatedAt(),rows,f==null?null:map(f));}private OrderRefundResponse map(OrderRefundEntity e){return new OrderRefundResponse(e.getId(),e.getRefundNo(),e.getReturnId(),e.getOrderId(),e.getCustomerId(),e.getRefundAmount(),e.getStatus(),e.getExternalReference(),e.getCompletedAt(),e.getVersion());}}
